function fcas_storage_status_show(config, idioma = 'pt') { if (!config || typeof config !== 'object' || typeof config.usado !== 'number' || typeof config.total !== 'number' || config.total <= 0) return ''; const lang = String(idioma).toLowerCase() === 'en' ? 'en' : 'pt'; const fmt = function(b) { const e = Math.floor(Math.log(b || 1) / Math.log(1024)); return (b / Math.pow(1024, e)).toFixed(1) + ' ' + ['B', 'KB', 'MB', 'GB', 'TB', 'PB'][e]; }; const pct = Math.min(Math.round((config.usado / config.total) * 100), 100); const cor = pct >= 90 ? '#e71d36' : '#2575fc'; const titulo = config.titulo || (lang === 'en' ? 'Storage Status' : 'Armazenamento'); const txtAlerta = lang === 'en' ? 'Low storage space! Consider freeing up files.' : 'Espaço quase cheio! Considere liberar arquivos.'; const txtSucesso = lang === 'en' ? 'Your storage space is secure.' : 'Seu espaço de armazenamento está seguro.'; const txtLabel = lang === 'en' ? 'Used' : 'Usado'; if (!document.getElementById('fcas_storage_style_unique')) { const style = document.createElement('style'); style.id = 'fcas_storage_style_unique'; style.textContent = '.fcas-storage-overlay{width:100%;display:flex;justify-content:center;align-items:center;padding:20px;box-sizing:border-box}.fcas-storage-container{background:#fff;padding:30px;border-radius:12px;box-shadow:0 10px 30px rgba(0,0,0,0.15);width:100%;box-sizing:border-box;text-align:center;font-family:sans-serif;animation:fcasStorageAnim 0.3s ease-out;margin:auto;word-break:break-word}.fcas-storage-header{display:flex;align-items:center;gap:12px;margin-bottom:15px}.fcas-storage-icon svg{width:40px;height:40px}.fcas-storage-container h2{margin:0;color:#222;font-size:1.3rem;font-weight:700}.fcas-storage-bar-bg{width:100%;height:12px;background:#e0e0e0;border-radius:6px;overflow:hidden;margin-bottom:8px}.fcas-storage-bar-fill{height:100%;transition:width 0.5s ease-out,background-color 0.3s}.fcas-storage-text{font-size:0.85rem;color:#888;text-align:left}@keyframes fcasStorageAnim{from{opacity:0;transform:scale(0.92)}to{opacity:1;transform:scale(1)}}@media(max-width:480px){.fcas-storage-container{padding:20px}.fcas-storage-container h2{font-size:1.1rem}}'; document.head.appendChild(style); } return `<div class="fcas-storage-overlay"><div class="fcas-storage-container"><div class="fcas-storage-header"><div class="fcas-storage-icon"><svg xmlns="http://w3.org" viewBox="0 0 24 24"><rect x="2" y="3" width="20" height="7" rx="1.5" fill="none" stroke="${cor}" stroke-width="2"/><line x1="6" y1="6.5" x2="14" y2="6.5" stroke="${cor}" stroke-width="2" stroke-linecap="round"/><circle cx="18" cy="6.5" r="1.5" fill="${cor}"/><rect x="2" y="14" width="20" height="7" rx="1.5" fill="none" stroke="${cor}" stroke-width="2"/><line x1="6" y1="17.5" x2="14" y2="17.5" stroke="${cor}" stroke-width="2" stroke-linecap="round"/><circle cx="18" cy="17.5" r="1.5" fill="${cor}"/></svg></div><h2>${titulo}</h2></div><div style="display:flex;justify-content:space-between;margin-bottom:8px;font-size:0.95rem;color:#333"><span>${pct}% ${txtLabel}</span><span>${fmt(config.usado)} / ${fmt(config.total)}</span></div><div class="fcas-storage-bar-bg"><div class="fcas-storage-bar-fill" style="width:${pct}%;background:${cor}"></div></div><div class="fcas-storage-text">${pct >= 90 ? txtAlerta : txtSucesso}</div></div></div>`; }
function fcas_newsletter_show(config) { if (!config || typeof config !== 'object' || !config.titulo || !config.mensagem) return ''; const botaoTexto = config.botaoTexto || 'Inscrever-se'; const placeholder = config.placeholder || 'Seu melhor e-mail'; const action = config.action || '#'; const nomeCampo = config.nomeCampo || 'email'; if (!document.getElementById('fcas_news_style_unique')) { const style = document.createElement('style'); style.id = 'fcas_news_style_unique'; style.textContent = '.fcas-news-overlay{width:100%;display:flex;justify-content:center;align-items:center;padding:20px;box-sizing:border-box}.fcas-news-container{background:#fff;padding:30px;border-radius:12px;box-shadow:0 10px 30px rgba(0,0,0,0.15);width:100%;box-sizing:border-box;text-align:center;font-family:sans-serif;animation:fcasNewsAnim 0.3s ease-out;margin:auto;word-break:break-word}.fcas-news-icon svg{width:50px;height:50px;fill:#011627}.fcas-news-container h2{margin:15px 0 10px;color:#222;font-size:1.4rem;line-height:1.2;font-weight:700;word-break:break-word}.fcas-news-container p{margin:0 0 20px;color:#555;font-size:0.95rem;line-height:1.6;word-break:break-word}.fcas-news-form{display:flex;flex-direction:column;gap:12px;width:100%}.fcas-news-input{width:100%;padding:12px;border:1px solid #ccc;border-radius:6px;font-size:0.95rem;box-sizing:border-box;outline:none;transition:border-color 0.2s}.fcas-news-input:focus{border-color:#011627}.fcas-news-btn{background:#011627;color:#fff;border:none;padding:12px;font-size:0.95rem;font-weight:600;border-radius:6px;cursor:pointer;width:100%;transition:opacity 0.2s}.fcas-news-btn:hover{opacity:0.9}@keyframes fcasNewsAnim{from{opacity:0;transform:scale(0.92)}to{opacity:1;transform:scale(1)}}@media(max-width:480px){.fcas-news-container{padding:20px}.fcas-news-container h2{font-size:1.2rem}.fcas-news-container p{font-size:0.88rem}}'; document.head.appendChild(style); } return `<div class="fcas-news-overlay"><div class="fcas-news-container"><div class="fcas-news-icon"><svg xmlns="http://w3.org" viewBox="0 0 24 24"><path d="M20 4H4c-1.1 0-1.99.9-1.99 2L2 18c0 1.1.9 2 2 2h16c1.1 0 2-.9 2-2V6c0-1.1-.9-2-2-2zm0 4l-8 5-8-5V6l8 5 8-5v2z"/></svg></div><h2>${config.titulo}</h2><p>${config.mensagem}</p><form class="fcas-news-form" action="${action}" method="POST"><input type="email" name="${nomeCampo}" class="fcas-news-input" placeholder="${placeholder}" required><button type="submit" class="fcas-news-btn">${botaoTexto}</button></form></div></div>`; }

