function fcas_lightbox_book(listaTextos, paginaInicial){const textosValidos=(listaTextos||[]).filter(function(t){return t&&t.trim()!=='';});if(textosValidos.length===0){return '<div class="fcas-lightbox-book"></div>';}const estiloExistente=document.getElementById('fcas-lightbox-styles');if(!estiloExistente){const style=document.createElement('style');style.id='fcas-lightbox-styles';style.textContent='.fcas-lightbox-book{display:flex;flex-direction:column;gap:15px;width:100%;max-width:1200px;margin:0 auto;padding:20px;box-sizing:border-box;position:relative}.fcas-lightbox-page{display:none;background-color:#ffffff;border:1px solid #e0e0e0;box-shadow:0 4px 6px rgba(0,0,0,0.05);padding:40px;min-height:400px;box-sizing:border-box;flex-direction:column;justify-content:flex-start;word-wrap:break-word;width:100%;position:relative}.fcas-lightbox-page.fcas-active{display:flex}.fcas-lightbox-num{position:absolute;bottom:15px;font-family:sans-serif;font-size:12px;color:#9ca3af;font-weight:600;pointer-events:none}.fcas-lightbox-page.fcas-esq .fcas-lightbox-num{left:20px}.fcas-lightbox-page.fcas-dir .fcas-lightbox-num{right:20px}.fcas-lightbox-controls{display:flex;justify-content:space-between;margin-top:20px;width:100%;gap:15px}.fcas-lightbox-btn{background:#2563eb;color:#ffffff;border:none;border-radius:50px;cursor:pointer;padding:12px;display:flex;align-items:center;justify-content:center;box-shadow:0 4px 6px rgba(37,99,235,0.2);transition:background 0.2s,transform 0.2s,box-shadow 0.2s;flex:1;max-width:100%;box-sizing:border-box}.fcas-lightbox-btn:hover{background:#1d4ed8;transform:translateY(-1px);box-shadow:0 6px 12px rgba(37,99,235,0.3)}.fcas-lightbox-btn:active{transform:translateY(1px);box-shadow:0 2px 4px rgba(37,99,235,0.2)}.fcas-lightbox-btn svg{width:24px;height:24px;fill:currentColor}.fcas-lightbox-btn[disabled]{background:#e5e7eb;color:#9ca3af;cursor:not-allowed;pointer-events:none;box-shadow:none;transform:none}@media(min-width:768px){.fcas-lightbox-book{flex-direction:row;flex-wrap:wrap;justify-content:center}.fcas-lightbox-page{width:calc(50% - 10px);min-height:500px; color:#000;}.fcas-lightbox-page.fcas-sozinha{width:calc(50% - 10px);margin:0 auto}.fcas-lightbox-controls{margin-top:30px;width:100%}.fcas-lightbox-btn{flex:none;width:50px;height:50px;padding:0}}';document.head.appendChild(style);}if(!window['nav_book']){window['nav_book']=function(b,dir){let pIdx=parseInt(b.getAttribute('data-pagina')||'0');let total=parseInt(b.getAttribute('data-total')||'0');let d=window.innerWidth>=768;if(dir===-1){if(d){if(pIdx===1){pIdx=0;}else if(pIdx>1){pIdx-=2;}}else{if(pIdx>0)pIdx--;}}else{if(d){if(pIdx===0){pIdx=1;}else if(pIdx+2<total){pIdx+=2;}else if(pIdx+1<total){pIdx+=1;}}else{if(pIdx+1<total)pIdx++;}}b.setAttribute('data-pagina',pIdx);window['att_book'](b);};window['att_book']=function(b){let pIdx=parseInt(b.getAttribute('data-pagina')||'0');let total=parseInt(b.getAttribute('data-total')||'0');let p=b.querySelectorAll('.fcas-lightbox-page');let d=window.innerWidth>=768;if(pIdx>=total){pIdx=total-1;b.setAttribute('data-pagina',pIdx);}for(let i=0;i<p.length;i++){p[i].classList.remove('fcas-active','fcas-sozinha');}let bp=b.querySelector('.fcas-prev');let bn=b.querySelector('.fcas-next');if(!d){if(p[pIdx])p[pIdx].classList.add('fcas-active');if(bp)bp.disabled=pIdx===0;if(bn)bn.disabled=pIdx===total-1;}else{if(pIdx===0){if(p[0])p[0].classList.add('fcas-active','fcas-sozinha');if(bp)bp.disabled=true;if(bn)bn.disabled=total<=1;}else{if(p[pIdx])p[pIdx].classList.add('fcas-active');let pProx=pIdx+1;if(pProx<total&&pProx%2===0){if(p[pProx])p[pProx].classList.add('fcas-active');}else if(!p[pProx]){if(p[pIdx])p[pIdx].classList.add('fcas-sozinha');}if(bp)bp.disabled=false;if(bn)bn.disabled=pIdx+1>=total||pIdx+2>=total;}}};window.addEventListener('resize',function(){document.querySelectorAll('.fcas-lightbox-book').forEach(function(b){window['att_book'](b);});});}let pIni=parseInt(paginaInicial)||1;if(pIni<1)pIni=1;if(pIni>textosValidos.length)pIni=textosValidos.length;let pIdxInicial=pIni-1;if(window.innerWidth>=768&&pIdxInicial>0&&pIdxInicial%2===0){pIdxInicial--;}const htmlString='<div class="fcas-lightbox-book" data-pagina="'+pIdxInicial+'" data-total="'+textosValidos.length+'">'+textosValidos.map(function(texto,idx){let c='';if(idx===pIdxInicial){c=' fcas-active';if(pIdxInicial===0&&window.innerWidth>=768){c+=' fcas-sozinha';}}else if(window.innerWidth>=768&&pIdxInicial>0&&idx===pIdxInicial+1&&idx%2===0){c=' fcas-active';}let lado=idx%2===0?' fcas-esq':' fcas-dir';if(idx===0)lado=' fcas-dir';return '<div class="fcas-lightbox-page'+c+lado+'">'+texto+'<div class="fcas-lightbox-num">'+(idx+1)+'</div></div>';}).join('')+(textosValidos.length>1?'<div class="fcas-lightbox-controls"><button class="fcas-lightbox-btn fcas-prev"'+(pIdxInicial===0?' disabled':'')+' onclick="window[\'nav_book\'](this.closest(\'.fcas-lightbox-book\'),-1)"><svg viewBox="0 0 24 24"><path d="M15.41 7.41L14 6l-6 6 6 6 1.41-1.41L10.83 12z"/></svg></button><button class="fcas-lightbox-btn fcas-next"'+((window.innerWidth>=768&&(pIdxInicial+1>=textosValidos.length||pIdxInicial+2>=textosValidos.length))||(window.innerWidth<768&&pIdxInicial===textosValidos.length-1)?' disabled':'')+' onclick="window[\'nav_book\'](this.closest(\'.fcas-lightbox-book\'),1)"><svg viewBox="0 0 24 24"><path d="M10 6L8.59 7.41 13.17 12l-4.58 4.59L10 18l6-6z"/></svg></button></div>':'')+'</div>';return htmlString;}

